            .iter()
            .all(|c| !c.starts_with("BAMTS-C00")),
        "N.E.A must resolve as a type reference (const enum): {:?}",
        checked.diagnostics()
    );

    let checked = check_text("namespace N { export enum E { A } } type Value = N.E;");
    assert!(checker_codes(&checked).is_empty());
}

