    let result = check_text(
        "class MyBase {
                 static S1: number = 5;
                 f = () => 5;
             }
             class MyDerived extends MyBase {
                 foo() {
                     var l1 = super.S1;
                     var l3 = super.f;
                     var l4 = super.toString;
                 }
             }",
