            "import { add } from './a'; add('x', 2);",
        ],
        &[(1, 0, 0)],
    );
    assert!(
        program_codes(&wrong_arg).contains(&super::ARGUMENT_NOT_ASSIGNABLE.as_str()),
        "{:?}",
