                 return value;
             }\
             function fromOverlappingUnions<
                 T extends { a: 1 | 2 } & { a: 2 | 3 }
             >(value: T['a']): 2 {
                 return value;
             }\
             function fromDistributedIntersection<
                 T extends ({ a: { x: string } } | { a: { b: number } })
