        "declare var cond: boolean;\nwhile (cond) function w() { }\nw();",
        ProgramCheckOptions::standard()
            .with_target(Some("es2015"))
            .with_strict(true),
    );
    assert!(
        checker_codes_of(&result).is_empty(),
        "{:?}",
        result.diagnostics()
    );
}

