    assert_eq!(c036_count, 1, "expected exactly 1 C036, got {codes:?}");
    assert_eq!(c086_count, 1, "expected exactly 1 C086, got {codes:?}");
}

#[test]
fn grounded_cell_compound_null_matches_authority_multiset() {
